import ast
omens = {"eval", "exec", "open", "__import__"}
def read_omens(speech):
    return [n.id for n in ast.walk(ast.parse(speech))
            if isinstance(n, ast.Name) and n.id in omens]
print(read_omens("eval(x)"), read_omens("2+2"))
assert read_omens("eval(x)") == ["eval"] and read_omens("2+2") == []
